-- Composite integrity, append-only facts, JSON bounds and finite numerics.
select ok(exists(select 1 from pg_constraint where conrelid='erp.pc_build_projects'::regclass and conname='pc_projects_id_org_branch_unique'),'PC project owner tuple is unique');
select ok(exists(select 1 from pg_constraint where conrelid='erp.pc_build_revisions'::regclass and conname='pc_revisions_owner_unique'),'PC revision owner tuple is unique');
select ok(exists(select 1 from pg_constraint where conrelid='erp.pc_build_revisions'::regclass and conname='pc_revisions_supersedes_fk'),'Revision ancestry is same-owner constrained');
select ok(exists(select 1 from pg_constraint where conrelid='erp.pc_build_components'::regclass and conname='pc_components_line_unique'),'Component lines are unique');
select ok(exists(select 1 from pg_constraint where conrelid='erp.pc_build_components'::regclass and conname='pc_components_slot_unique'),'Component slots are unique');
