select ok(exists(select 1 from pg_constraint where conrelid='erp.trade_in_evaluations'::regclass and conname='trade_evaluations_supersedes_fk'),'Evaluation ancestry is same-trade constrained');
select ok(exists(select 1 from pg_constraint where conrelid='erp.trade_in_releases'::regclass and conname='trade_releases_eval_fk'),'Release evaluation is same-trade constrained');
