select ok(exists(select 1 from pg_constraint where conrelid='erp.trade_in_sale_payment_events'::regclass and conname='trade_payment_reverses_fk'),'Payment reversal is same-tenant constrained');
select ok(exists(select 1 from pg_constraint where conrelid='erp.trade_in_sale_payment_events'::regclass and conname='trade_payment_reversal_unique'),'Payment reversal event can be recorded only once');
select ok(exists(select 1 from pg_constraint where conrelid='erp.trade_in_imei_results'::regclass and conname='trade_imei_results_request_owner_fk'),'IMEI results retain exact request ownership');
select ok(exists(select 1 from pg_indexes where schemaname='erp' and tablename='trade_in_imei_results' and indexname='trade_imei_provider_result_once'),'Each IMEI request has at most one provider result');
select ok(exists(select 1 from pg_indexes where schemaname='erp' and tablename='trade_in_refurbishments' and indexname='trade_refurbishment_repair_once'),'A delivered repair cost can be captured by only one trade-in');
select ok((select pg_get_constraintdef(oid) like '%pg_column_size(configuration) <= 262144%' from pg_constraint where conrelid='erp.pc_build_revisions'::regclass and conname='pc_build_revisions_configuration_check'),'Revision JSON is bounded');
select ok((select pg_get_constraintdef(oid) like '%pg_column_size(specification_snapshot) <= 65536%' from pg_constraint where conrelid='erp.pc_build_components'::regclass and conname='pc_build_components_specification_snapshot_check'),'Component spec JSON is bounded');
select ok((select pg_get_constraintdef(oid) like '%unit_cost_snapshot <>%NaN%' from pg_constraint where conrelid='erp.pc_build_components'::regclass and conname='pc_build_components_unit_cost_snapshot_check'),'Component costs reject NaN');
select ok((select pg_get_constraintdef(oid) like '%pg_column_size(evidence) <= 262144%' from pg_constraint where conrelid='erp.trade_in_imei_results'::regclass and conname='trade_in_imei_results_evidence_check'),'IMEI evidence is bounded');
select ok((select pg_get_constraintdef(oid) like '%appraised_value_base <>%NaN%' from pg_constraint where conrelid='erp.trade_in_evaluations'::regclass and conname='trade_in_evaluations_appraised_value_base_check'),'Evaluation values reject NaN');
select ok((select pg_get_constraintdef(oid) like '%actual_cost_base <>%NaN%' from pg_constraint where conrelid='erp.trade_in_refurbishments'::regclass and conname='trade_in_refurbishments_actual_cost_base_check'),'Refurbishment costs reject NaN');
select ok((select coalesce(pg_get_constraintdef(oid),'') like '%accepted_value_base%' and coalesce(pg_get_constraintdef(oid),'') like '%refurbishment_cost_base%' from pg_constraint where conrelid='erp.trade_in_releases'::regclass and conname='trade_in_releases_check'),'Release total cost reconciles exactly');
