select ok(exists(select 1 from pg_trigger where tgrelid='erp.pc_component_lineage'::regclass and tgname='pc_component_lineage_immutable'),'Component lineage is append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.trade_in_provenance_reviews'::regclass and tgname='trade_in_provenance_reviews_immutable'),'Provenance reviews are append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.trade_in_imei_results'::regclass and tgname='trade_in_imei_results_immutable'),'IMEI results are append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.trade_in_evaluations'::regclass and tgname='trade_in_evaluations_immutable'),'Evaluations are append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.trade_in_releases'::regclass and tgname='trade_in_releases_immutable'),'Releases are append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.trade_in_sale_payment_events'::regclass and tgname='trade_in_sale_payment_events_immutable'),'Payment links are append-only');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.pc_compatibility_spec_versions'::regclass and tgname='pc_spec_versions_immutable'),'PC specs are immutable');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.pc_compatibility_rules'::regclass and tgname='pc_rules_immutable'),'PC rules are immutable');
select ok(exists(select 1 from pg_trigger where tgrelid='erp.pc_test_template_versions'::regclass and tgname='pc_test_versions_immutable'),'PC tests are immutable');

