select ok((select qual like '%organization_id = %current_organization_id()%has_permission(''pc_builds.view''%branch_id%' from pg_policies where schemaname='erp' and tablename='pc_build_projects' and policyname='pc_projects_select'),'PC project RLS is tenant and branch scoped');
select ok((select qual like '%organization_id = %current_organization_id()%has_permission(''trade_ins.view''%branch_id%' from pg_policies where schemaname='erp' and tablename='trade_ins' and policyname='trade_ins_select'),'Trade-in RLS is tenant and branch scoped');
select ok((select qual like '%pc_build_components.organization_id%has_permission(''pc_builds.view''%' from pg_policies where schemaname='erp' and tablename='pc_build_components' and policyname='pc_components_select'),'Component child RLS resolves its owning branch');
select is((select count(*) from pg_policies where schemaname='erp' and tablename='trade_in_imei_results' and cmd in('INSERT','ALL')),0::bigint,'No client policy permits provider-result insertion');
select is(has_table_privilege('anon','erp.trade_ins','SELECT'),false,'Anon cannot read trade-ins');
