-- Static behavioral contract: locks, exactness, gates, redaction and wrappers.
create function pg_temp.normalized_functiondef(target regprocedure) returns text language sql stable as $$
  select lower(regexp_replace(pg_get_functiondef(target),'[[:space:]]+','','g'))
$$;
select ok(pg_temp.normalized_functiondef('erp.create_pc_build_revision(uuid,uuid,uuid,jsonb,jsonb,text,text)') like '%inventory_cost_balances%','Quantity component cost uses WAC');
select ok(pg_temp.normalized_functiondef('erp.create_pc_build_revision(uuid,uuid,uuid,jsonb,jsonb,text,text)') like '%serialized_acquisition_costs%','Serialized component cost uses specific cost');
select ok(pg_temp.normalized_functiondef('erp.create_pc_build_revision(uuid,uuid,uuid,jsonb,jsonb,text,text)') like '%specification_snapshot%warranty_snapshot%','Revision freezes specs and warranty');
select ok(pg_temp.normalized_functiondef('erp.record_pc_compatibility_run(uuid,text,text)') like '%required_slots%','Compatibility checks required slots');
select ok(pg_temp.normalized_functiondef('erp.record_pc_compatibility_run(uuid,text,text)') like '%pc_compatibility_rules%','Compatibility uses pinned rules');
select ok(pg_temp.normalized_functiondef('erp.record_pc_compatibility_run(uuid,text,text)') like '%matchedisnottrue%','Missing compatibility attributes cannot preserve a passing run');
select ok(pg_temp.normalized_functiondef('erp.reserve_pc_build_components(uuid,uuid,timestamptz,jsonb,text,text)') like '%create_stock_reservation%''pc_build''%','PC reservation uses existing source wrapper');
select ok(pg_temp.normalized_functiondef('erp.reserve_pc_build_components(uuid,uuid,timestamptz,jsonb,text,text)') like '%reservationmustexactlymatchrevisioncomponents%','PC reservation is an exact multiset');
select ok(pg_temp.normalized_functiondef('erp.assert_pc_project_mutable(uuid,uuid)') like '%pcprojectisterminal%','PC project mutation is terminal-state guarded');
